#include <setjmp.h>
#include <stdio.h>
int main() {
    sigjmp_buf env;
    int val = sigsetjmp(env, 1);  // Saves the context and signal mask
    if (val == 0) {
        printf("Executing initial code\n");
        siglongjmp(env, 1);  // Jumps back, restoring the signal mask
    } else {
        printf("Returned from siglongjmp with signal mask restored\n");
    }
    return 0;
}
